import sys

def surfaceArea(A):
	ans = 0
	for i in range(len(A)):
		for j in range(len(A[0])):
			for (dx, dy) in [(-1, 0), (0, 1), (1, 0), (0, -1)]:
				nx = j + dx
				ny = i + dy
				if 0 <= nx < len(A[0]) and 0 <= ny < len(A):
					if nx >= j and ny >= i:
						ans += abs(A[i][j] - A[ny][nx])
				else:
					ans += A[i][j]
	return ans
